package com.hbm.missile.completion;
import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.phys.Vec3;import net.neoforged.neoforge.network.PacketDistributor;import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
/** Original ParticleBurstPacket(stained_glass,meta3), radius measured from the logic EMP entity. */
public record EmpMachineSparks(BlockPos position) implements CustomPacketPayload {
 public static final Type<EmpMachineSparks> TYPE=new Type<>(MissileContent.id("emp_machine_sparks"));public static final StreamCodec<RegistryFriendlyByteBuf,EmpMachineSparks> CODEC=StreamCodec.of((b,p)->b.writeBlockPos(p.position),b->new EmpMachineSparks(b.readBlockPos()));@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}public static void register(RegisterPayloadHandlersEvent event){event.registrar("1").playToClient(TYPE,CODEC,(packet,context)->context.enqueueWork(()->com.hbm.client.missile.completion.MissileClientEffects.emp(packet)));}public static void send(ServerLevel level,Vec3 origin,BlockPos pos){var packet=new EmpMachineSparks(pos);for(var player:level.players())if(player.distanceToSqr(origin)<2500)PacketDistributor.sendToPlayer(player,packet);}
}
